using Microsoft.EntityFrameworkCore;
using Shameen.Api.Models;

namespace Shameen.Api.Data;
public sealed class TransferDbContext(DbContextOptions<TransferDbContext> options) : DbContext(options) {
    public DbSet<Branch> Branches => Set<Branch>(); public DbSet<DestinationCity> DestinationCities => Set<DestinationCity>(); public DbSet<Employee> Employees => Set<Employee>(); public DbSet<Transfer> Transactions => Set<Transfer>(); public DbSet<OperatingDay> OperatingDays => Set<OperatingDay>(); public DbSet<FloatAdjustment> FloatAdjustments => Set<FloatAdjustment>();
    protected override void OnModelCreating(ModelBuilder model) {
        model.Entity<DestinationCity>().HasIndex(c => new { c.Country, c.City }).IsUnique(); model.Entity<DestinationCity>().Property(c => c.Country).HasMaxLength(80); model.Entity<DestinationCity>().Property(c => c.City).HasMaxLength(100);
        model.Entity<Branch>().HasIndex(b => b.Name).IsUnique(); model.Entity<Branch>().Property(b => b.Name).HasMaxLength(80); model.Entity<Branch>().Property(b => b.City).HasMaxLength(80); model.Entity<Branch>().Property(b => b.Country).HasMaxLength(80).HasDefaultValue("");
        model.Entity<Employee>().HasIndex(e => e.Email).IsUnique(); model.Entity<Employee>().HasIndex(e => e.BranchId); model.Entity<Employee>().Property(e => e.Email).HasMaxLength(320); model.Entity<Employee>().Property(e => e.PasswordHash).HasMaxLength(512); model.Entity<Employee>().Property(e => e.CollectionCountry).HasMaxLength(80); model.Entity<Employee>().Property(e => e.FloatBalance).HasPrecision(18,2); model.Entity<Employee>().Property(e => e.FloatAssigned).HasPrecision(18,2); model.Entity<Employee>().HasOne(e => e.Branch).WithMany().HasForeignKey(e => e.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<Transfer>().HasIndex(t => t.Reference).IsUnique(); model.Entity<Transfer>().HasIndex(t => new { t.BranchId, t.CreatedAtUtc }); model.Entity<Transfer>().Property(t => t.Amount).HasPrecision(18,2); model.Entity<Transfer>().Property(t => t.Reference).HasMaxLength(32); model.Entity<Transfer>().Property(t => t.Status).HasMaxLength(32); model.Entity<Transfer>().Property(t => t.DestinationCity).HasMaxLength(100); model.Entity<Transfer>().Property(t => t.CollectionReference).HasMaxLength(120); model.Entity<Transfer>().HasOne(t => t.Employee).WithMany(e => e.Transfers).HasForeignKey(t => t.EmployeeId).OnDelete(DeleteBehavior.Restrict); model.Entity<Transfer>().HasOne(t => t.Branch).WithMany().HasForeignKey(t => t.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<OperatingDay>().HasIndex(d => new { d.Date, d.BranchId }).IsUnique(); model.Entity<OperatingDay>().Property(d => d.OpeningFloat).HasPrecision(18,2); model.Entity<OperatingDay>().Property(d => d.ClosingFloat).HasPrecision(18,2); model.Entity<OperatingDay>().HasOne(d => d.Branch).WithMany().HasForeignKey(d => d.BranchId).OnDelete(DeleteBehavior.Restrict);
        model.Entity<FloatAdjustment>().HasIndex(a => new { a.OperatingDayId, a.EmployeeId, a.CreatedAtUtc }); model.Entity<FloatAdjustment>().Property(a => a.PreviousAmount).HasPrecision(18,2); model.Entity<FloatAdjustment>().Property(a => a.NewAmount).HasPrecision(18,2); model.Entity<FloatAdjustment>().Property(a => a.Reason).HasMaxLength(500); model.Entity<FloatAdjustment>().HasOne<OperatingDay>().WithMany().HasForeignKey(a => a.OperatingDayId).OnDelete(DeleteBehavior.Restrict); model.Entity<FloatAdjustment>().HasOne<Employee>().WithMany().HasForeignKey(a => a.EmployeeId).OnDelete(DeleteBehavior.Restrict); model.Entity<FloatAdjustment>().HasOne<Employee>().WithMany().HasForeignKey(a => a.ActorEmployeeId).OnDelete(DeleteBehavior.Restrict);
    }
}
